arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -d "token=<TOKEN>" -d "channel=C_INC" -d "limit=500" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d); sys.exit(1)
for m in d['messages']:
    t=m.get('text','')
    if m.get('thread_ts') is None and ('freeze' in t.lower() or 'deploy' in t.lower()):
        print(m['ts'], '|', m['user'], '|', t.replace(chr(10),' ')[:120], '| replies:', m.get('reply_count'))
"

